package com.cowave.search.jdbc.service

import com.cowave.search.jdbc.dto.CreateJdbcRequest
import com.cowave.search.jdbc.dto.JdbcInfoResponse
import com.cowave.search.jdbc.dto.JdbcTestRequest
import com.cowave.search.jdbc.dto.JdbcTestResponse
import com.cowave.search.jdbc.dto.UpdateJdbcRequest
import com.cowave.search.jdbc.infrastructure.JdbcInfoRepository
import com.cowave.search.jdbc.model.JdbcInfo
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class JdbcService(
    private val jdbcInfoRepository: JdbcInfoRepository,
) {
    private val logger = LoggerFactory.getLogger(JdbcService::class.java)

    fun findAll(clusterId: String): List<JdbcInfoResponse> =
        jdbcInfoRepository
            .findAllByClusterId(clusterId)
            .map { it.toResponse() }

    fun create(
        clusterId: String,
        request: CreateJdbcRequest,
    ): JdbcInfoResponse {
        val entity =
            JdbcInfo(
                clusterId = clusterId,
                name = request.name,
                provider = request.provider,
                driver = request.driver,
                address = request.address,
                port = request.port,
                dbName = request.dbName,
                user = request.user,
                password = request.password,
                url = request.url,
                params = request.params,
            )
        return jdbcInfoRepository.save(entity).toResponse()
    }

    fun update(
        clusterId: String,
        id: String,
        request: UpdateJdbcRequest,
    ): JdbcInfoResponse {
        val entity =
            jdbcInfoRepository.findByClusterIdAndId(clusterId, id)
                ?: throw IllegalArgumentException("JDBC 설정을 찾을 수 없습니다: $id")
        request.name?.let { entity.name = it }
        request.provider?.let { entity.provider = it }
        request.driver?.let { entity.driver = it }
        request.address?.let { entity.address = it }
        request.port?.let { entity.port = it }
        request.dbName?.let { entity.dbName = it }
        request.user?.let { entity.user = it }
        request.password?.let { entity.password = it }
        request.url?.let { entity.url = it }
        request.params?.let { entity.params = it }
        return jdbcInfoRepository.save(entity).toResponse()
    }

    fun delete(
        clusterId: String,
        id: String,
    ) {
        jdbcInfoRepository.deleteByClusterIdAndId(clusterId, id)
    }

    fun testConnection(request: JdbcTestRequest): JdbcTestResponse =
        runCatching {
            Class.forName(request.driver)
            java.sql.DriverManager
                .getConnection(request.url, request.user, request.password)
                .use { true }
            JdbcTestResponse(success = true, message = "연결 성공")
        }.getOrElse { e ->
            logger.warn("JDBC 연결 테스트 실패: {}", e.message)
            JdbcTestResponse(success = false, message = e.message ?: "연결 실패")
        }

    private fun JdbcInfo.toResponse() =
        JdbcInfoResponse(
            id = id,
            clusterId = clusterId,
            name = name,
            provider = provider,
            driver = driver,
            address = address,
            port = port,
            dbName = dbName,
            user = user,
            url = url,
            params = params,
        )
}

