package com.cowave.search.proxy.service

import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.apache.hc.core5.http.ContentType
import org.apache.hc.core5.http.io.entity.StringEntity
import org.elasticsearch.client.Request
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import jakarta.servlet.http.HttpServletRequest

@Service
class ProxyService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(ProxyService::class.java)

    /** 차단할 위험 패턴: path + method 조합 */
    private val blockedPatterns =
        listOf(
            Pair("PUT", "_cluster/settings"),
            Pair("POST", "_shutdown"),
            Pair("DELETE", "_all"),
        )

    fun proxy(
        clusterId: String,
        method: String,
        esPath: String,
        queryString: String?,
        body: String?,
    ): ProxyResult {
        // 위험 API 차단
        val upperMethod = method.uppercase()
        blockedPatterns.forEach { (blockedMethod, blockedPath) ->
            if (upperMethod == blockedMethod && esPath.contains(blockedPath)) {
                logger.warn("차단된 ES API 요청: {} {}", method, esPath)
                return ProxyResult(403, "application/json", """{"error":"forbidden","path":"$esPath"}""")
            }
        }

        val targetPath = if (queryString.isNullOrBlank()) esPath else "$esPath?$queryString"

        return runCatching {
            val restClient = clientFactory.getLowLevelClient(clusterId)
            val request = Request(method, targetPath)
            if (!body.isNullOrBlank()) {
                request.entity = StringEntity(body, ContentType.APPLICATION_JSON)
            }
            val response = restClient.performRequest(request)
            val responseBody = response.entity?.content?.bufferedReader()?.readText() ?: ""
            val statusCode = response.statusLine?.statusCode ?: 200
            val contentType =
                response.entity?.contentType ?: "application/json"
            ProxyResult(statusCode, contentType, responseBody)
        }.getOrElse { e ->
            logger.error("ES 프록시 오류 [{} {}]: {}", method, esPath, e.message)
            ProxyResult(500, "application/json", """{"error":"${e.message?.replace("\"", "'")}"}""")
        }
    }

    data class ProxyResult(
        val statusCode: Int,
        val contentType: String,
        val body: String,
    )
}

package com.cowave.search.proxy.service

import co.elastic.clients.transport.rest5_client.low_level.Request
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class ProxyService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(ProxyService::class.java)

    /** 차단할 위험 패턴: HTTP메서드 + 경로 부분문자열 */
    private val blockedPatterns =
        listOf(
            "PUT" to "_cluster/settings",
            "POST" to "_shutdown",
            "DELETE" to "_all",
        )

    fun proxy(
        clusterId: String,
        method: String,
        esPath: String,
        queryString: String?,
        body: String?,
    ): ProxyResult {
        val upperMethod = method.uppercase()
        blockedPatterns.forEach { (blockedMethod, blockedPath) ->
            if (upperMethod == blockedMethod && esPath.contains(blockedPath)) {
                logger.warn("차단된 ES API 요청: {} {}", method, esPath)
                return ProxyResult(403, "application/json", """{"error":"forbidden","path":"$esPath"}""")
            }
        }

        val targetPath = if (queryString.isNullOrBlank()) esPath else "$esPath?$queryString"

        return runCatching {
            val restClient = clientFactory.getLowLevelClient(clusterId)
            val request = Request(upperMethod, targetPath)
            if (!body.isNullOrBlank()) {
                request.setJsonEntity(body)
            }
            val response = restClient.performRequest(request)
            val responseBody = response.entity?.content?.bufferedReader()?.readText() ?: ""
            val statusCode = response.getStatusCode()
            val contentType = response.getHeader("Content-Type") ?: "application/json"
            ProxyResult(statusCode, contentType, responseBody)
        }.getOrElse { e ->
            logger.error("ES 프록시 오류 [{} {}]: {}", method, esPath, e.message)
            ProxyResult(500, "application/json", """{"error":"${e.message?.replace("\"", "'")}"}""")
        }
    }

    data class ProxyResult(
        val statusCode: Int,
        val contentType: String,
        val body: String,
    )
}

package com.cowave.search.proxy.controller

import com.cowave.search.proxy.service.ProxyService
import jakarta.servlet.http.HttpServletRequest
import org.springframework.http.HttpStatus
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/elasticsearch")
class ProxyController(
    private val proxyService: ProxyService,
) {
    /**
     * ES API 프록시: 모든 HTTP 메서드를 그대로 ES로 전달.
     *
     * - `/elasticsearch/**` → ES 원본 URI로 변환 (`/elasticsearch` prefix 제거)
     * - `proxyUri` 쿼리 파라미터로 URI 오버라이드 가능
     */
    @RequestMapping("/**")
    fun proxy(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestParam(required = false) proxyUri: String?,
        @RequestBody(required = false) body: String?,
        request: HttpServletRequest,
    ): ResponseEntity<String> {
        // /elasticsearch 접두사 제거 후 ES 경로 추출
        val rawPath = request.requestURI.removePrefix(request.contextPath)
        val esPath = proxyUri ?: rawPath.removePrefix("/elasticsearch").ifBlank { "/" }

        // 쿼리 파라미터에서 proxyUri 제외하고 나머지를 queryString으로 전달
        val queryString =
            request.queryString
                ?.split("&")
                ?.filter { !it.startsWith("proxyUri=") }
                ?.joinToString("&")
                ?.ifBlank { null }

        val result = proxyService.proxy(clusterId, request.method, esPath, queryString, body)

        val mediaType =
            runCatching {
                MediaType.parseMediaType(result.contentType)
            }.getOrElse { MediaType.APPLICATION_JSON }

        return ResponseEntity
            .status(HttpStatus.valueOf(result.statusCode))
            .contentType(mediaType)
            .body(result.body)
    }
}

package com.cowave.search.tools.service

import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.slf4j.LoggerFactory
import org.springframework.cache.annotation.Cacheable
import org.springframework.stereotype.Service

@Service
class ToolsService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(ToolsService::class.java)

    /**
     * 설치된 플러그인 목록 조회.
     * 각 플러그인에 대해 테스트 분석을 수행하고 성공한 것만 반환한다.
     */
    @Cacheable("plugins")
    fun getPlugins(clusterId: String): List<PluginInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val catResponse =
                client
                    .cat()
                    .plugins { it.h("name", "component", "version") }
            catResponse.valueBody().mapNotNull { record ->
                val name = record.name() ?: return@mapNotNull null
                val component = record.component() ?: ""
                val version = record.version() ?: ""
                // 플러그인 테스트 분석 (성공하면 유효한 플러그인으로 판단)
                val valid =
                    runCatching {
                        client.indices().analyze { a -> a.analyzer(component).text("test") }
                        true
                    }.getOrDefault(false)
                if (valid) PluginInfo(name = name, component = component, version = version) else null
            }
        }.getOrElse { e ->
            logger.warn("플러그인 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    /**
     * 플러그인 기반 텍스트 형태소 분석.
     * `_analysis-product-name` 플러그인 호출 후 중복 제거 및 형태소 합산.
     */
    fun analyzeText(
        clusterId: String,
        request: AnalysisRequest,
    ): AnalysisResponse {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response =
                client.indices().analyze { a ->
                    a
                        .analyzer(request.analyzer)
                        .text(request.text)
                        .apply {
                            request.index?.let { index(it) }
                        }
                }
            val tokens =
                response
                    .tokens()
                    .map { it.token() }
                    .distinct() // 중복 제거
            AnalysisResponse(
                analyzer = request.analyzer,
                text = request.text,
                tokens = tokens,
                tokenCount = tokens.size,
            )
        }.getOrElse { e ->
            logger.warn("형태소 분석 실패 [{}]: {}", clusterId, e.message)
            AnalysisResponse(
                analyzer = request.analyzer,
                text = request.text,
                tokens = emptyList(),
                tokenCount = 0,
                error = e.message,
            )
        }
    }

    data class PluginInfo(
        val name: String,
        val component: String,
        val version: String,
    )

    data class AnalysisRequest(
        val analyzer: String,
        val text: String,
        val index: String? = null,
    )

    data class AnalysisResponse(
        val analyzer: String,
        val text: String,
        val tokens: List<String>,
        val tokenCount: Int,
        val error: String? = null,
    )
}

