package com.cowave.search.migration.service

import com.cowave.search.collection.infrastructure.CollectionRepository
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.jdbc.infrastructure.JdbcInfoRepository
import com.fasterxml.jackson.databind.ObjectMapper
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import org.springframework.web.multipart.MultipartFile

@Service
class MigrationService(
    private val clientFactory: ElasticsearchClientFactory,
    private val collectionRepository: CollectionRepository,
    private val jdbcInfoRepository: JdbcInfoRepository,
    private val objectMapper: ObjectMapper,
) {
    private val logger = LoggerFactory.getLogger(MigrationService::class.java)

    /**
     * 클러스터 설정 일괄 백업.
     * 선택한 항목(pipelines, collections, jdbc, templates)을 JSON으로 직렬화하여 반환.
     */
    fun download(
        clusterId: String,
        request: BackupRequest,
    ): BackupData {
        val client = clientFactory.getClient(clusterId)

        val pipelines: Map<String, Any> =
            if (request.pipelines) {
                runCatching {
                    val response = client.ingest().getPipeline { it }
                    @Suppress("UNCHECKED_CAST")
                    objectMapper.convertValue(response.pipelines(), Map::class.java) as Map<String, Any>
                }.getOrElse { e ->
                    logger.warn("파이프라인 백업 실패: {}", e.message)
                    emptyMap()
                }
            } else {
                emptyMap()
            }

        val collections: List<Map<String, Any>> =
            if (request.collections) {
                runCatching {
                    collectionRepository
                        .findAllByClusterId(clusterId)
                        .map {
                            @Suppress("UNCHECKED_CAST")
                            objectMapper.convertValue(it, Map::class.java) as Map<String, Any>
                        }
                }.getOrElse { e ->
                    logger.warn("컬렉션 백업 실패: {}", e.message)
                    emptyList()
                }
            } else {
                emptyList()
            }

        val jdbc: List<Map<String, Any>> =
            if (request.jdbc) {
                runCatching {
                    jdbcInfoRepository
                        .findAllByClusterId(clusterId)
                        .map {
                            @Suppress("UNCHECKED_CAST")
                            objectMapper.convertValue(it, Map::class.java) as Map<String, Any>
                        }
                }.getOrElse { e ->
                    logger.warn("JDBC 백업 실패: {}", e.message)
                    emptyList()
                }
            } else {
                emptyList()
            }

        val templates: Map<String, Any> =
            if (request.templates) {
                runCatching {
                    val response = client.indices().getIndexTemplate { it }
                    response
                        .indexTemplates()
                        .associate { t ->
                            @Suppress("UNCHECKED_CAST")
                            t.name() to (objectMapper.convertValue(t, Map::class.java) as Map<String, Any>)
                        }
                }.getOrElse { e ->
                    logger.warn("템플릿 백업 실패: {}", e.message)
                    emptyMap()
                }
            } else {
                emptyMap()
            }

        return BackupData(
            pipelines = pipelines,
            collections = collections,
            jdbc = jdbc,
            templates = templates,
            comments = "DSearch backup - clusterId=$clusterId",
        )
    }

    /**
     * 백업 파일 업로드 복원.
     * 각 단계 독립 처리 (실패해도 다음 단계 진행).
     */
    fun upload(
        clusterId: String,
        file: MultipartFile,
    ): RestoreResult {
        val client = clientFactory.getClient(clusterId)
        val results = mutableMapOf<String, String>()

        val backupData =
            runCatching {
                objectMapper.readValue(file.bytes, BackupData::class.java)
            }.getOrElse { e ->
                return RestoreResult(
                    success = false,
                    message = "파일 파싱 실패: ${e.message}",
                    details = emptyMap(),
                )
            }

        // 파이프라인 복원: xpack 제외, version 제거
        if (backupData.pipelines.isNotEmpty()) {
            var successCount = 0
            backupData.pipelines.forEach { (id, pipelineRaw) ->
                runCatching {
                    if (id.startsWith("xpack")) return@runCatching
                    @Suppress("UNCHECKED_CAST")
                    val pipeline = (pipelineRaw as? Map<String, Any>)?.toMutableMap() ?: return@runCatching
                    pipeline.remove("version")
                    val pipelineJson = objectMapper.writeValueAsString(pipeline)
                    client.ingest().putPipeline { req ->
                        req.id(id).withJson(java.io.StringReader(pipelineJson))
                    }
                    successCount++
                }.onFailure { e -> logger.warn("파이프라인 복원 실패 [{}]: {}", id, e.message) }
            }
            results["pipelines"] = "복원 $successCount/${backupData.pipelines.size}"
        }

        // 템플릿 복원
        if (backupData.templates.isNotEmpty()) {
            var successCount = 0
            backupData.templates.forEach { (name, templateRaw) ->
                runCatching {
                    val templateJson = objectMapper.writeValueAsString(templateRaw)
                    client.indices().putIndexTemplate { req ->
                        req.name(name).withJson(java.io.StringReader(templateJson))
                    }
                    successCount++
                }.onFailure { e -> logger.warn("템플릿 복원 실패 [{}]: {}", name, e.message) }
            }
            results["templates"] = "복원 $successCount/${backupData.templates.size}"
        }

        return RestoreResult(success = true, message = "복원 완료", details = results)
    }

    data class BackupRequest(
        val pipelines: Boolean = true,
        val collections: Boolean = true,
        val jdbc: Boolean = true,
        val templates: Boolean = true,
    )

    data class BackupData(
        val pipelines: Map<String, Any> = emptyMap(),
        val collections: List<Map<String, Any>> = emptyList(),
        val jdbc: List<Map<String, Any>> = emptyList(),
        val templates: Map<String, Any> = emptyMap(),
        val comments: String = "",
    )

    data class RestoreResult(
        val success: Boolean,
        val message: String,
        val details: Map<String, String>,
    )
}

